import React, { useState } from 'react';
import { CharacterData, Faction } from '../types';
import { NPC_VOLUMES } from '../constants';
import { Card, Button } from './Shared';
import { User as UserIcon, Skull, Sun, Moon, Ghost, Plus, ShieldCheck, Sword, Wand2, Crown, Link as LinkIcon, Terminal, Settings, ChevronLeft, ChevronRight } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';
/* [DIALECT] */ import { useDialect } from '../dialect_module/DialectContext';
import { useUI } from '../context/UIContext';

interface Props {
  characters: CharacterData[];
  onSelect: (id: string) => void;
  onCreate: () => void;
  onOpenSettings?: () => void;
}

const Roster: React.FC<Props> = ({ characters, onSelect, onCreate, onOpenSettings }) => {
  const { isAdmin } = useAuth();
  /* [DIALECT] */ const { t, handleLetterClick, handleSlashClick, isInputMode, inputBuffer, isDialectUnlocked } = useDialect();
  const { showAlert } = useUI();
  const [activeTab, setActiveTab] = useState<Faction>(Faction.LIGHT);
  const [npcVolume, setNpcVolume] = useState<string>(NPC_VOLUMES[0]);

  // Tab ordering for navigation
  const tabs = [Faction.LIGHT, Faction.DARK, Faction.GRAVEYARD, Faction.NPC];

  const handleNextTab = () => {
      const idx = tabs.indexOf(activeTab);
      setActiveTab(tabs[(idx + 1) % tabs.length]);
  };

  const handlePrevTab = () => {
      const idx = tabs.indexOf(activeTab);
      setActiveTab(tabs[(idx - 1 + tabs.length) % tabs.length]);
  };

  const filtered = characters.filter(c => {
    if (!c.profile) return false;

    const isCompanion = c.profile.faction === Faction.NPC && c.profile.npc_volume === "Спутники и Рабы";
    if (c.meta.master_id && !isCompanion) return false;

    if (c.profile.faction !== activeTab) return false;
    if (activeTab === Faction.NPC && c.profile.npc_volume !== npcVolume) return false;
    return true;
  });

  // --- Theme Logic ---
  const getTheme = (f: Faction) => {
    switch (f) {
      case Faction.LIGHT: 
        return {
          tab: "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.5)]",
          topGradient: "from-amber-500/10 via-amber-500/5 to-transparent",
          bottomGradient: "from-amber-500/10 via-amber-500/5 to-transparent",
          topLine: "bg-amber-400/30 shadow-[0_0_15px_rgba(251,191,36,0.3)]",
          glowColor: "from-amber-900/60"
        };
      case Faction.DARK: 
        return {
          tab: "text-violet-400 drop-shadow-[0_0_8px_rgba(139,92,246,0.5)]",
          topGradient: "from-violet-900/20 via-violet-900/5 to-transparent",
          bottomGradient: "from-violet-900/20 via-violet-900/5 to-transparent",
          topLine: "bg-violet-500/30 shadow-[0_0_15px_rgba(139,92,246,0.3)]",
          glowColor: "from-violet-900/60"
        };
      case Faction.NPC: 
        return {
          tab: "text-red-500 drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]",
          topGradient: "from-red-900/15 via-red-900/5 to-transparent",
          bottomGradient: "from-red-900/15 via-red-900/5 to-transparent",
          topLine: "bg-red-500/30 shadow-[0_0_15px_rgba(239,68,68,0.3)]",
          glowColor: "from-red-900/60"
        };
      case Faction.GRAVEYARD: 
        return {
          tab: "text-slate-400 drop-shadow-[0_0_8px_rgba(148,163,184,0.5)]",
          topGradient: "from-slate-800/20 via-slate-800/5 to-transparent",
          bottomGradient: "from-slate-800/20 via-slate-800/5 to-transparent",
          topLine: "bg-slate-500/30 shadow-[0_0_15px_rgba(148,163,184,0.3)]",
          glowColor: "from-slate-800/60"
        };
      default: 
        return { tab: "", topGradient: "", bottomGradient: "", topLine: "", glowColor: "" };
    }
  };

  const theme = getTheme(activeTab);

  const getVolumeLabel = (vol: string) => {
    if (vol.startsWith("Том 1")) return t('vol_1', vol);
    if (vol.startsWith("Том 2")) return t('vol_2', vol);
    if (vol.startsWith("Том 3")) return t('vol_3', vol);
    if (vol.startsWith("Том 4")) return t('vol_4', vol);
    if (vol.startsWith("Том 5")) return t('vol_5', vol);
    if (vol.startsWith("Том 6")) return t('vol_6', vol);
    if (vol === "Спутники и Рабы") return t('vol_servants', vol);
    if (vol === "Отрицательные NPC") return t('vol_neg', vol);
    if (vol === "Положительные NPC") return t('vol_pos', vol);
    return vol;
  };

  const getLabelKey = (faction: Faction) => 
      faction === Faction.LIGHT ? 'fac_light' : 
      faction === Faction.DARK ? 'fac_dark' :
      faction === Faction.NPC ? 'fac_npc' : 'fac_graveyard';

  const TabButton = ({ faction, icon: Icon }: { faction: Faction, icon: any }) => {
    const isActive = activeTab === faction;
    const labelKey = getLabelKey(faction);

    return (
      <button
        onClick={() => setActiveTab(faction)}
        className={`relative flex items-center gap-2 px-4 md:px-6 py-3 font-serif font-bold uppercase tracking-widest text-[10px] md:text-xs transition-all whitespace-nowrap flex-shrink-0 ${
          isActive ? theme.tab : "text-slate-600 hover:text-slate-400"
        }`}
      >
        <Icon size={16} />
        {t(labelKey, faction)}
        {isActive && (
           <div className={`absolute bottom-0 left-0 w-full h-px ${theme.topLine.split(' ')[0]}`}></div>
        )}
      </button>
    );
  };

  const renderInteractiveTitle = (text: string) => {
    return text.split('').map((char, i) => (
      <span 
        key={i} 
        onClick={(e) => {
           e.stopPropagation();
           handleLetterClick(char);
        }}
        className="hover:text-violet-400 transition-colors cursor-pointer select-none active:scale-90 inline-block"
      >
        {char}
      </span>
    ));
  };

  return (
    <div className="relative flex flex-col w-full h-[calc(100dvh-3rem)] md:h-[100dvh] overflow-hidden">

      {/* Background Image Layer - Adjusted opacity and position */}
      <div className="absolute inset-0 z-0 pointer-events-none">
          <img 
            src="https://vadwslmqajbbmklrhnzu.supabase.co/storage/v1/object/public/Juul-D-Page/character-roster-bg.jpg" 
            className="w-full h-full object-cover opacity-60 blur-[3px]" 
            alt="Background"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/60 to-transparent" />
      </div>

      {/* Scrollable Content Layer */}
      <div className="flex-1 overflow-y-auto custom-scrollbar px-4 md:px-8 pt-4 md:pt-8 pb-32 w-full relative z-10">

            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                {/* Title & Logo */}
                <h1 className="text-2xl md:text-5xl font-gothic font-normal text-transparent bg-clip-text bg-gradient-to-r from-slate-200 via-violet-200 to-slate-200 tracking-[0.07em] uppercase flex items-center gap-3 drop-shadow-[0_0_15px_rgba(139,92,246,0.3)] opacity-90">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" fill="none" className="w-6 h-6 md:w-10 md:h-10 opacity-80 drop-shadow-glow">
                        <path d="M50 5 L93.3 30 V80 L50 105 L6.7 80 V30 L50 5 Z" fill="#0891b2" transform="translate(0 -5)"/>
                        <text x="50" y="53" fontFamily="sans-serif" fontWeight="900" fontSize="50" fill="white" textAnchor="middle">C</text>
                        <text x="50" y="87" fontFamily="sans-serif" fontWeight="900" fontSize="50" fill="white" textAnchor="middle">T</text>
                    </svg>
                    <div className="flex items-center gap-2">
                        <span className="flex">{renderInteractiveTitle(t('app_title_1', 'Трекер'))}</span> 
                        <span 
                        onClick={(e) => {
                            e.stopPropagation();
                            handleSlashClick();
                        }}
                        className="text-violet-700 cursor-pointer hover:text-violet-400 transition-colors select-none active:scale-90 inline-block drop-shadow-glow"
                        >
                        //
                        </span> 
                        <span className="flex">{renderInteractiveTitle(t('app_title_2', 'Персонажей'))}</span>
                    </div>
                </h1>

                {/* Auth Panel */}
                {isAdmin && (
                    <div className="flex items-center gap-3 bg-[#050b14] p-1.5 rounded-sm border border-violet-900/20 shadow-lg">
                        <div className="flex items-center gap-2 px-3">
                        <ShieldCheck size={14} className="text-violet-500" />
                        <span className="text-[10px] font-bold text-violet-300 uppercase tracking-wider font-serif">Admin</span>
                        </div>

                        {onOpenSettings && (
                        <Button onClick={onOpenSettings} size="sm" variant="ghost" className="text-slate-400 hover:text-white">
                            <Settings size={16} />
                        </Button>
                        )}

                        <Button onClick={onCreate} size="sm" className="shadow-glow bg-violet-900/50 border-violet-500/50 hover:bg-violet-800">
                        {/* [DIALECT] */}
                        <Plus size={14} /> {t('btn_new', 'New')}
                        </Button>
                    </div>
                )}
            </div>

            {/* Tabs - Desktop (Scrollable/Standard) */}
            <div className="hidden md:flex border-b border-violet-900/10 overflow-x-auto no-scrollbar z-20 relative">
                <TabButton faction={Faction.LIGHT} icon={Sun} />
                <TabButton faction={Faction.DARK} icon={Moon} />
                <TabButton faction={Faction.GRAVEYARD} icon={Skull} />
                <TabButton faction={Faction.NPC} icon={Ghost} />
            </div>

            {/* Tabs - Mobile (Arrow Navigation) */}
            <div className="md:hidden flex items-center justify-between border-b border-violet-900/20 pb-4 mb-4">
                <button onClick={handlePrevTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronLeft size={24} />
                </button>
                <div className={`font-serif font-bold uppercase tracking-widest text-lg ${theme.tab}`}>
                    {t(getLabelKey(activeTab), activeTab)}
                </div>
                <button onClick={handleNextTab} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <ChevronRight size={24} />
                </button>
            </div>

            {/* Content Area */}
            <div className="relative">

                {/* Top Lamp & Separator within scrolling content */}
                <div className={`absolute top-0 left-0 right-0 h-48 bg-gradient-to-b ${theme.topGradient} pointer-events-none z-0 transition-all duration-700`}></div>
                <div className={`absolute top-0 left-0 right-0 h-px w-full ${theme.topLine} z-10 transition-all duration-700`}></div>

                <div className="py-8 relative z-10 min-h-[500px]">
                    {activeTab === Faction.NPC && (
                    <div className="mb-6 p-4 bg-[#050b14] border border-violet-900/30 relative z-10 rune-clip-r max-w-lg shadow-[0_0_20px_rgba(0,0,0,0.5)]">
                        {/* [DIALECT] */}
                        <label className="text-[10px] uppercase font-bold text-slate-500 mb-2 block tracking-widest font-serif">{t('lbl_npc_vol', "Архив Бестиария")}</label>
                        <select 
                        value={npcVolume} 
                        onChange={(e) => setNpcVolume(e.target.value)}
                        className="bg-[#020617] border border-slate-800 text-slate-300 text-sm rounded-sm w-full p-2 focus:border-violet-600 focus:shadow-glow outline-none font-serif tracking-wide"
                        >
                        {NPC_VOLUMES.map(v => <option key={v} value={v}>{getVolumeLabel(v)}</option>)}
                        </select>
                    </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 relative z-10">
                    {filtered.map(char => (
                        <Card key={char.id} className="cursor-pointer hover:border-violet-500/40 transition-all hover:bg-[#0b0f19] bg-[#050b14] border-violet-900/20 group relative overflow-hidden shadow-lg hover:shadow-[0_0_15px_rgba(139,92,246,0.1)]" >
                        <div onClick={() => onSelect(char.id)} className="h-full flex flex-col">
                            <div className="flex items-start gap-4 mb-4">

                            {/* Avatar with Level Badge */}
                            <div className="relative flex-shrink-0">
                                <div className="w-16 h-16 bg-[#020617] flex items-center justify-center border border-slate-800 overflow-hidden grayscale group-hover:grayscale-0 transition-all duration-500 rune-clip">
                                {char.meta.avatar_url ? <img src={char.meta.avatar_url} className="w-full h-full object-cover" /> : <UserIcon size={32} className="text-slate-700" />}
                                </div>
                                {/* Level Badge Top-Left */}
                                <div className="absolute -top-1 -left-1 w-5 h-5 bg-black border border-violet-900/50 flex items-center justify-center shadow-lg z-10">
                                <span className="text-[10px] font-bold text-violet-300 font-mono">{char.profile.level}</span>
                                </div>
                            </div>

                            <div className="flex-1 min-w-0">
                                <h3 className="font-bold font-serif text-lg text-slate-200 group-hover:text-violet-200 transition-colors truncate tracking-wide">{char.profile.name}</h3>

                                {/* Master Link Indicator */}
                                {char.meta.master_id && char.profile.faction === Faction.NPC && (
                                <div className="flex items-center gap-1 text-[10px] text-violet-400 mb-1 font-serif uppercase tracking-wider">
                                    <LinkIcon size={10} /> 
                                    {/* [DIALECT] */}
                                    <span>{t('lbl_linked', 'Связан')}</span>
                                </div>
                                )}

                                {/* Save Status / Death Status */}
                                {char.profile.faction === Faction.GRAVEYARD ? (
                                <div className="flex items-center gap-1.5 mt-1">
                                    <Skull size={12} className="text-slate-500" />
                                    <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500/80 truncate max-w-[150px]" title={char.meta.save_status_reason || "Причина смерти не указана"}>
                                        {/* [DIALECT] */}
                                        {char.meta.save_status_reason || t('meta_death_unknown', "Умер")}
                                    </span>
                                </div>
                                ) : (
                                    <div className="flex items-center gap-1.5 mt-1">
                                    {char.meta.save_status ? (
                                        <>
                                            <ShieldCheck size={12} className="text-emerald-500" />
                                            <span className="text-[10px] font-bold uppercase tracking-wider text-emerald-500/80 font-serif">
                                                {/* [DIALECT] */}
                                                {t('meta_save_ok', 'Есть сейв')}
                                            </span>
                                        </>
                                    ) : (
                                        <>
                                            <Skull size={12} className="text-red-500" />
                                            <span className="text-[10px] font-bold uppercase tracking-wider text-red-500/80 truncate max-w-[150px]" title={char.meta.save_status_reason || t('meta_save_lost', "Сейв потерян")} />
                                        </>
                                    )}
                                    </div>
                                )}

                                {/* Stats Row with Icons */}
                                <div className="flex gap-2 mt-2 opacity-60 group-hover:opacity-100 transition-opacity">
                                <div className="flex items-center gap-1 text-[10px] text-red-400">
                                    <Sword size={10} /> <span className="font-mono font-bold">{char.stats.phys}</span>
                                </div>
                                <div className="flex items-center gap-1 text-[10px] text-violet-400">
                                    <Wand2 size={10} /> <span className="font-mono font-bold">{char.stats.magic}</span>
                                </div>
                                <div className="flex items-center gap-1 text-[10px] text-emerald-400">
                                    <Crown size={10} /> <span className="font-mono font-bold">{char.stats.unique}</span>
                                </div>
                                </div>

                            </div>
                            </div>

                            {/* Equipment Preview */}
                            <div className="text-[10px] text-slate-500 truncate mt-auto pt-3 border-t border-violet-900/10 font-sans">
                            {/* [DIALECT] */}
                            {char.equipment.wearable.filter(w => w.is_equipped).map(w => w.name).join(", ") || t('msg_no_eq', "Нет экипировки")}
                            </div>
                        </div>
                        </Card>
                    ))}
                    {filtered.length === 0 && (
                        <div className="col-span-full flex flex-col items-center justify-center py-16 text-slate-700 border border-dashed border-slate-800 rounded-lg">
                        <Ghost size={48} className="mb-4 opacity-20"/>
                        {/* [DIALECT] */}
                        <span className="text-sm font-bold uppercase tracking-widest font-serif">{t('msg_empty', 'Здесь никого нет')}</span>
                        </div>
                    )}
                    </div>
                </div>
            </div>
        </div>

        {/* Bottom Glow (Fixed pinned to bottom) */}
        <div className={`absolute bottom-0 left-0 right-0 w-full h-32 bg-gradient-to-t ${theme.glowColor} to-transparent pointer-events-none z-20 opacity-80`}></div>

        {/* [DIALECT] Easter Egg Input Window - Fixed in the main container */}
        {isInputMode && !isDialectUnlocked && (
          <div className="absolute bottom-4 left-4 md:left-1/2 md:-translate-x-1/2 md:bottom-8 z-[100] animate-fade-in w-[calc(100%-2rem)] max-w-sm pointer-events-none">
              <div className="bg-black/90 border border-violet-900 rounded-lg p-3 shadow-[0_0_20px_rgba(139,92,246,0.3)] backdrop-blur-sm rune-clip pointer-events-auto relative">
                <div className="flex items-center gap-2 mb-1 justify-between">
                  <div className="flex items-center gap-2">
                      <Terminal size={14} className="text-violet-500 animate-pulse"/>
                      <span className="text-[10px] font-mono text-violet-300 uppercase tracking-widest">Input Sequence</span>
                  </div>
                </div>
                <div className="bg-slate-900/50 border border-slate-800 rounded p-2 h-10 flex items-center justify-center">
                    <span className="font-serif text-lg text-violet-400 tracking-[0.2em] uppercase drop-shadow-[0_0_5px_rgba(167,139,250,0.8)]">
                      {inputBuffer || <span className="opacity-20">_ _ _ _ _ _</span>}
                    </span>
                </div>
                <div className="text-center mt-1">
                    <span className="text-[9px] text-slate-600 uppercase">Tap title letters</span>
                </div>
              </div>
          </div>
        )}
    </div>
  );
};

export default Roster;

import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { LayoutGrid, Users, Sword, Library, LogOut, Hexagon, ChevronLeft, ChevronRight, X, ShieldCheck } from 'lucide-react';
import { NavItem } from '../../types';

interface SidebarProps {
  isDesktopCollapsed: boolean;
  toggleDesktopSidebar: () => void;
  isMobileOpen: boolean;
  closeMobileSidebar: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  isDesktopCollapsed, 
  toggleDesktopSidebar,
  isMobileOpen,
  closeMobileSidebar
}) => {
  const { signOut, user, triggerAdminSequence, isAdmin } = useAuth();
  const navigate = useNavigate();

  const navItems: NavItem[] = [
    { label: 'Хаб', path: '/', icon: LayoutGrid },
    { label: 'Ростер', path: '/roster', icon: Users },
    { label: 'Последовательность', path: '/battle', icon: Sword },
    { label: 'Архивы Мира', path: '/lore', icon: Library },
  ];

  const handleLogout = async () => {
    await signOut();
    navigate('/auth');
    if (window.innerWidth < 768) closeMobileSidebar();
  };

  const handleLinkClick = () => {
    if (window.innerWidth < 768) closeMobileSidebar();
  }

  return (
    <aside 
      className={`
        fixed inset-y-0 left-0 z-50
        bg-[#050b14]/95 backdrop-blur-md border-r border-violet-900/20 
        flex flex-col transition-[width,transform] duration-300 ease-in-out
        ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'} 
        md:translate-x-0
        ${isDesktopCollapsed ? 'w-20' : 'w-64'}
        overflow-visible
      `}
    >
      {/* Mobile Close Button - Transparent, higher and more right */}
      <button 
        onClick={closeMobileSidebar}
        className="md:hidden absolute top-1 right-1 text-slate-400 hover:text-white p-2 z-[60] bg-transparent rounded-full"
      >
        <X size={24} />
      </button>

      {/* Desktop Toggle Button - Positioned absolutely relative to the sidebar edge */}
      <button 
        onClick={toggleDesktopSidebar}
        className="hidden md:flex absolute -right-3 top-24 bg-slate-900 border border-violet-500/50 text-violet-300 rounded-full p-1 shadow-[0_0_10px_rgba(139,92,246,0.3)] hover:text-white hover:scale-110 transition-all z-[60]"
      >
        {isDesktopCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
      </button>

      {/* Header / Logo */}
      <div className="h-24 flex items-center justify-center border-b border-violet-900/20 overflow-hidden shrink-0 relative">

        {/* LOGO CONTAINER - Double Click for Admin */}
        <div 
          className="flex items-center gap-3 cursor-pointer select-none"
          onDoubleClick={triggerAdminSequence}
          title="Juul-D System"
        >
           {/* Icon: Always visible */}
           <div className={`relative flex items-center justify-center group transition-all duration-300 ${isDesktopCollapsed ? 'scale-110' : ''}`}>
             <Hexagon className={`w-10 h-10 ${isAdmin ? 'text-emerald-500 fill-emerald-900/20' : 'text-violet-600 fill-violet-900/20'} stroke-[1.5px] group-hover:stroke-violet-400 transition-colors`} />
             <span className={`absolute font-fantasy font-bold text-sm ${isAdmin ? 'text-emerald-200' : 'text-violet-200'} tracking-tighter pt-0.5 group-hover:text-white transition-colors`}>JD</span>
           </div>

           {/* Text: Hidden when desktop collapsed */}
           <h1 
             className={`
               font-fantasy text-2xl font-bold text-transparent bg-clip-text bg-gradient-to-r ${isAdmin ? 'from-emerald-200 to-teal-200' : 'from-violet-200 to-fuchsia-200'} tracking-widest transition-all duration-300 origin-left
               ${isDesktopCollapsed ? 'w-0 opacity-0 scale-0 hidden md:block' : 'w-auto opacity-100 scale-100'}
             `}
           >
             JUUL-D
           </h1>
        </div>
      </div>

      {/* Navigation */}
      <nav className="flex-1 py-8 flex flex-col gap-2 px-3 overflow-y-auto custom-scrollbar overflow-x-hidden">
        {navItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            onClick={handleLinkClick}
            className={({ isActive }) => `
              group flex items-center gap-4 px-3 py-3 rounded-lg transition-all duration-300 overflow-hidden relative
              ${isActive 
                ? 'bg-violet-900/20 text-violet-200 border border-violet-500/30 shadow-[0_0_10px_rgba(139,92,246,0.1)]' 
                : 'text-slate-400 hover:bg-white/5 hover:text-violet-300'
              }
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title={isDesktopCollapsed ? item.label : ''}
          >
            {({ isActive }) => (
              <>
                <item.icon 
                  className={`
                    min-w-[24px] w-6 h-6 transition-all duration-300 shrink-0
                    ${isActive ? 'drop-shadow-[0_0_5px_rgba(139,92,246,0.5)]' : ''}
                  `} 
                />

                <span 
                  className={`
                    font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300
                    ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
                  `}
                >
                  {item.label}
                </span>
              </>
            )}
          </NavLink>
        ))}
      </nav>

      {/* User Footer */}
      <div className="p-4 border-t border-violet-900/20 shrink-0 overflow-hidden">
        <div className="flex flex-col gap-2">
          {user && !isDesktopCollapsed && (
            <div className="flex flex-col mb-2 px-2 animate-fadeIn">
              <span className="text-xs text-slate-500 uppercase font-bold flex items-center gap-1">
                Вы вошли как {isAdmin && <ShieldCheck size={12} className="text-emerald-500" />}
              </span>
              <span className={`text-sm truncate font-mono ${isAdmin ? 'text-emerald-300' : 'text-violet-300'}`}>{user.email}</span>
            </div>
          )}

          <button 
            onClick={handleLogout}
            className={`
              flex items-center gap-4 px-3 py-2 rounded-lg text-slate-500 hover:text-red-400 hover:bg-red-900/10 transition-colors w-full
              ${isDesktopCollapsed ? 'justify-center' : ''}
            `}
            title="Выйти"
          >
            <LogOut className="w-5 h-5 min-w-[20px] shrink-0" />
            <span 
              className={`
                font-fantasy tracking-wider text-sm whitespace-nowrap transition-all duration-300
                ${isDesktopCollapsed ? 'opacity-0 w-0 md:hidden' : 'opacity-100 w-auto'}
              `}
            >
              Выйти
            </span>
          </button>
        </div>
      </div>
    </aside>
  );
};

