                         </div>
                         <div className="flex-1">
                            <input 
                              className="w-full bg-transparent border-b border-gray-800 focus:border-amber-500 text-gray-200 text-sm py-1 focus:outline-none transition-colors"
                              value={unit.label}
                              onChange={(e) => updateTimeUnit(idx, 'label', e.target.value)}
                            />
                         </div>
                         <div className="w-24 flex justify-center">
                            <button 
                              onClick={() => updateTimeUnit(idx, 'battle', !unit.battle)}
                              className={`px-3 py-1 rounded text-[10px] font-bold uppercase border transition-colors ${unit.battle ? 'bg-red-900/20 border-red-500/50 text-red-400' : 'bg-gray-800 border-gray-700 text-gray-600'}`}
                            >
                              {unit.battle ? 'Боевое' : 'Пассив'}
                            </button>
                         </div>
                         <button onClick={() => removeTimeUnit(idx)} className="text-gray-600 hover:text-red-500 p-2"><Trash2 size={16}/></button>
                      </div>
                    ))}
                  </div>

                  <div className="bg-[#13151c] border border-violet-500/20 rounded-lg p-6 mt-6">
                    <div className="text-sm text-amber-500 font-serif uppercase tracking-wider mb-4 flex items-center gap-2">
                       <Plus size={16} /> Новая Единица
                    </div>
                    <div className="grid grid-cols-12 gap-4 items-center">
                       <input 
                         className="col-span-3 bg-[#0b0d10] border border-gray-800 rounded p-3 text-sm text-white focus:border-amber-500/50 outline-none"
                         placeholder="Тег (напр. turn)"
                         value={newTimeTag}
                         onChange={(e) => setNewTimeTag(e.target.value)}
                       />
                       <input 
                         className="col-span-5 bg-[#0b0d10] border border-gray-800 rounded p-3 text-sm text-white focus:border-amber-500/50 outline-none"
                         placeholder="Метка (напр. Ход)"
                         value={newTimeLabel}
                         onChange={(e) => setNewTimeLabel(e.target.value)}
                         onKeyDown={(e) => e.key === 'Enter' && addTimeUnit()}
                       />
                       <div className="col-span-2 flex justify-center">
                          <label className="flex items-center gap-2 cursor-pointer text-[10px] uppercase font-bold text-gray-400 select-none hover:text-white">
                             <input 
                               type="checkbox" 
                               checked={newTimeBattle} 
                               onChange={e => setNewTimeBattle(e.target.checked)}
                               className="accent-amber-500 w-4 h-4"
                             />
                             Бой?
                          </label>
                       </div>
                       <button 
                          onClick={addTimeUnit} 
                          className="col-span-2 py-3 bg-amber-900/20 border border-amber-500/30 text-amber-400 text-xs font-bold uppercase tracking-widest hover:bg-amber-900/40 transition-all rounded"
                       >
                          Добавить
                       </button>
                    </div>
                  </div>
                </div>
             )}

             {/* --- BASIC ACTIONS TAB --- */}
             {activeTab === 'basic' && (
                 <div className="max-w-6xl mx-auto space-y-4">
                     {loadingActions ? (
                         <div className="text-center text-slate-500 py-10">Загрузка архива...</div>
                     ) : (
                         <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                             {basicActions.map((action, idx) => (
                                 <Card key={idx} className="bg-[#0b0d10] border-gray-800">
                                     <div className="flex justify-between items-start mb-2">
                                         <StyledInput 
                                            isEditMode={true} 
                                            value={action.name} 
                                            onChange={(e) => updateBasicAction(idx, 'name', e.target.value)}
                                            className="font-bold text-lg w-full text-emerald-400"
                                         />
                                         <button onClick={() => removeBasicAction(idx)} className="text-gray-600 hover:text-red-500 p-1"><Trash2 size={16}/></button>
                                     </div>

                                     <div className="flex flex-wrap gap-2 mb-2">
                                         <BonusInput isEditMode={true} bonuses={action.bonuses} onChange={b => updateBasicAction(idx, 'bonuses', b)} />
                                         <TimeInput icon={Clock} label="КД" isEditMode={true} val={action.cd} unit={action.cd_unit} onChangeVal={v => updateBasicAction(idx, 'cd', v)} onChangeUnit={u => updateBasicAction(idx, 'cd_unit', u)} options={editingTimeUnits} />
                                         <TimeInput icon={Hourglass} label="Длит." isEditMode={true} val={action.dur} unit={action.dur_unit} onChangeVal={v => updateBasicAction(idx, 'dur', v)} onChangeUnit={u => updateBasicAction(idx, 'dur_unit', u)} options={editingTimeUnits} />
                                         <TimeInput icon={Hash} label="Лимит" isEditMode={true} val={action.limit || 0} unit={action.limit_unit || ""} onChangeVal={v => updateBasicAction(idx, 'limit', v)} onChangeUnit={u => updateBasicAction(idx, 'limit_unit', u)} options={editingTimeUnits} />
                                     </div>

                                     <div className="mb-2">
                                         <TagInput isEditMode={true} tags={action.tags} onChange={t => updateBasicAction(idx, 'tags', t)} />
                                         <CommonTagToggles tags={action.tags} onChange={t => updateBasicAction(idx, 'tags', t)} />
                                     </div>

                                     <StyledTextarea isEditMode={true} value={action.desc_lore} onChange={e => updateBasicAction(idx, 'desc_lore', e.target.value)} className="text-sm italic text-gray-400 mb-2" placeholder="Худ. описание" />
                                     <StyledTextarea isEditMode={true} value={action.desc_mech} onChange={e => updateBasicAction(idx, 'desc_mech', e.target.value)} className="text-xs font-mono text-green-400" placeholder="Механика" />
                                 </Card>
                             ))}

                             <button onClick={addBasicAction} className="border-2 border-dashed border-gray-800 rounded-lg flex items-center justify-center text-gray-700 hover:text-emerald-500 hover:border-emerald-900 transition-all min-h-[200px]">
                                 <Plus size={32} />
                             </button>
                         </div>
                     )}
                 </div>
             )}
          </div>

          {/* Footer Actions */}
          <div className="relative z-10 p-5 border-t border-violet-500/20 bg-[#0b0d12]/90 backdrop-blur">
             <div className="flex gap-4">
               {activeTab === 'triggers' && (
                 <button onClick={saveTriggers} className="flex-1 py-3 bg-cyan-900/20 border border-cyan-500/50 text-cyan-300 font-serif uppercase tracking-widest text-sm hover:bg-cyan-900/40 hover:shadow-[0_0_15px_rgba(34,211,238,0.2)] transition-all">
                    Сохранить Триггеры
                 </button>
               )}
               {activeTab === 'injuries' && (
                 <button onClick={saveInjuriesHandler} className="flex-1 py-3 bg-red-900/20 border border-red-500/50 text-red-300 font-serif uppercase tracking-widest text-sm hover:bg-red-900/40 hover:shadow-[0_0_15px_rgba(248,113,113,0.2)] transition-all">
                    Обновить Протоколы Травм
                 </button>
               )}
               {activeTab === 'time' && (
                 <button onClick={saveTimeUnitsHandler} className="flex-1 py-3 bg-amber-900/20 border border-amber-500/50 text-amber-300 font-serif uppercase tracking-widest text-sm hover:bg-amber-900/40 hover:shadow-[0_0_15px_rgba(251,191,36,0.2)] transition-all">
                    Синхронизировать Время
                 </button>
               )}
               {activeTab === 'basic' && (
                 <button onClick={saveBasicActionsHandler} className="flex-1 py-3 bg-emerald-900/20 border border-emerald-500/50 text-emerald-300 font-serif uppercase tracking-widest text-sm hover:bg-emerald-900/40 hover:shadow-[0_0_15px_rgba(16,185,129,0.2)] transition-all">
                    Кодифицировать Действия
                 </button>
               )}
             </div>
          </div>

       </div>
    </div>
  );
};

export default GlobalSettingsModal;

import React, { useState, useEffect, useMemo } from 'react';
import { DndContext, DragEndEvent, DragOverlay, useSensor, useSensors, PointerSensor, DragStartEvent, pointerWithin } from '@dnd-kit/core';
import { BattleParticipant, LogEntry, SequenceNode, BattleStatus, CharacterTemplate } from './types';
import SourcePanel from './components/SourcePanel';
import SequenceCanvas from './components/SequenceCanvas';
import BattleLog from './components/BattleLog';
import { Modal } from './components/Modal';
import { updateBattle, getCharacters, createBattle, getBattles, calculateTraumaPenalty, deleteBattle, supabase } from './lib/supabase';
import { UserPlus, Save, Play, Square, List, RefreshCw } from 'lucide-react';
import { calculateSequenceTree } from './engine/calculator';

type ModalType = 'CREATE_BATTLE' | 'CONFIRM_SAVE' | 'CONFIRM_END' | 'FINALIZE_BATTLE' | 'ALERT' | 'CHAR_SELECT' | 'BATTLE_LIST' | 'CONFIRM_DELETE' | null;

interface BattleModuleProps {
  isAdmin?: boolean;
}

const BattleModule: React.FC<BattleModuleProps> = ({ isAdmin = false }) => {
  const [participants, setParticipants] = useState<BattleParticipant[]>([]);
  const [round, setRound] = useState<number>(0);
  const [status, setStatus] = useState<BattleStatus>('startup');
  const [battleName, setBattleName] = useState('Новый Бой');
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [battleId, setBattleId] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [allCharacters, setAllCharacters] = useState<CharacterTemplate[]>([]);
  const [savedBattles, setSavedBattles] = useState<any[]>([]);

  const [activeModal, setActiveModal] = useState<ModalType>(null);
  const [modalInput, setModalInput] = useState('');
  const [alertMessage, setAlertMessage] = useState('');
  const [pendingAction, setPendingAction] = useState<() => void>(() => {});

  const [charSearchTerm, setCharSearchTerm] = useState('');
  const [selectedFaction, setSelectedFaction] = useState<string>('All');
  const [selectedVolume, setSelectedVolume] = useState<string>('All');

  const [battleToDelete, setBattleToDelete] = useState<string | null>(null);

  const [tree, setTree] = useState<SequenceNode[]>([]);
  const [activeDragItem, setActiveDragItem] = useState<any>(null);
  const [activeNode, setActiveNode] = useState<SequenceNode | null>(null);

  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }));

  useEffect(() => {
    async function loadResources() {
        const { data: chars } = await getCharacters();
        if (chars && chars.length > 0) {
             setAllCharacters(chars);
        }
        const { data: battles } = await getBattles();
        if (battles) setSavedBattles(battles);
    }
    loadResources();
  }, []);

  // --- Filtering Logic ---
  const filteredCharacters = useMemo(() => {
    let result = [...allCharacters];
    // Use profile instead of identity
    result = result.filter(c => c.profile.faction !== 'Могильник');
    if (charSearchTerm) {
        const lower = charSearchTerm.toLowerCase();
        result = result.filter(c => c.profile.name.toLowerCase().includes(lower));
    }
    if (selectedFaction !== 'All') {
        result = result.filter(c => c.profile.faction === selectedFaction);
    }
    const isNpcLike = ['NPC', 'НПС', 'Бестиарий'].includes(selectedFaction);
    if (isNpcLike && selectedVolume !== 'All') {
         result = result.filter(c => c.profile.npc_volume === selectedVolume);
    }
    result.sort((a, b) => a.profile.name.localeCompare(b.profile.name));
    return result;
  }, [allCharacters, charSearchTerm, selectedFaction, selectedVolume]);

  const showAlert = (msg: string) => {
      setAlertMessage(msg);
      setActiveModal('ALERT');
  };

  const closeModal = () => {
      setActiveModal(null);
      setModalInput('');
      setAlertMessage('');
      setCharSearchTerm('');
      setSelectedFaction('All');
      setSelectedVolume('All');
  };

  const getStatusLabel = (s: string) => {
       if (s === 'active') return 'АКТИВЕН';
       if (s === 'finished') return 'ЗАВЕРШЕН';
       if (s === 'startup') return 'ПОДГОТОВКА';
       return s;
  };

  const getCharacterStyle = (faction: string) => {
      const f = (faction || '').toLowerCase();
      if (['светлые', 'light', 'свет'].includes(f)) return 'bg-amber-900/10 border-amber-600/50 hover:bg-amber-900/20 text-amber-100';
      if (['тёмные', 'dark', 'темные', 'тьма'].includes(f)) return 'bg-indigo-950/30 border-indigo-500/50 hover:bg-indigo-900/20 text-indigo-100';
      if (['npc', 'нпс', 'бестиарий'].includes(f)) return 'bg-red-950/20 border-red-800/50 hover:bg-red-900/20 text-red-100';
      return 'bg-panel border-violet-900/30 hover:border-violet-500/50 text-slate-200';
  };

  // --- Handlers ---
  const handleUpdateParticipant = (id: string, updates: any) => { setParticipants(prev => prev.map(p => p.instance_id === id ? { ...p, ...updates } : p)); };
  const handleToggleEquip = (pId: string, itemId: string) => { setParticipants(prev => prev.map(p => p.instance_id === pId ? { ...p, equipment: { ...p.equipment, wearable: p.equipment.wearable.map(i => i._id === itemId ? { ...i, is_equipped: !i.is_equipped } : i) } } : p)); };
  const handleRemoveParticipant = (id: string) => setParticipants(prev => prev.filter(p => p.instance_id !== id));

  const handleRemoveEffect = (pId: string, eId: string) => { 
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== pId) return p;
          const nextEffects = p.active_effects.filter(e => e.id !== eId);
          return { ...p, active_effects: nextEffects };
      }));
  };
  const handleRemoveCooldown = (pId: string, cId: string) => { 
      setParticipants(prev => prev.map(p => p.instance_id === pId ? { ...p, cooldowns: p.cooldowns.filter(c => c.id !== cId) } : p)); 
  };
  const handleAddInjury = (pId: string, tId: string) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== pId) return p;
          // use medcard
          const newInjuries = [...p.medcard.injuries, { count: 1, template_id: tId, custom_name: '' }];
          const trauma = calculateTraumaPenalty(newInjuries);
          return { ...p, medcard: { ...p.medcard, injuries: newInjuries }, battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq } };
      }));
  };
  const handleRemoveInjury = (pId: string, index: number) => {
      setParticipants(prev => prev.map(p => {
          if (p.instance_id !== pId) return p;
          const newInjuries = [...p.medcard.injuries];
          newInjuries.splice(index, 1);
          const trauma = calculateTraumaPenalty(newInjuries);
          return { ...p, medcard: { ...p.medcard, injuries: newInjuries }, battle_stats: { ...p.battle_stats, hp_penalty_current: trauma.total, trauma_phys: trauma.phys, trauma_mag: trauma.mag, trauma_uniq: trauma.uniq } };
      }));
  };
  const handleAddDebuff = (pId: string, name: string, tag: string, val: number, dur: number, unit: string, extraTags?: string) => {
      setParticipants(prev => prev.map(p => p.instance_id === pId ? { ...p, active_effects: [...p.active_effects, { id: `custom_${Date.now()}`, name, tags: [tag, extraTags || ''].filter(Boolean), bonuses: [{ val, stat: tag }], duration_left: dur, unit: unit || 'turn' }] } : p));
  };

  const loadBattle = async (id: string) => {
      setLoading(true);
      const { data: b } = await supabase.from('battles').select('*').eq('id', id).single();
      if (b) { setBattleId(b.id); setBattleName(b.name || 'Бой без названия'); setRound(b.round); setStatus(b.status || 'startup'); setLogs(b.sequence_log || []); setParticipants(b.participants_snapshot || []); }
      setLoading(false); setActiveModal(null);
  };
  const handleDeleteBattle = (id: string, e: React.MouseEvent) => { e.stopPropagation(); setBattleToDelete(id); setActiveModal('CONFIRM_DELETE'); };
  const confirmDeleteBattle = async () => { if (!battleToDelete) { setActiveModal('BATTLE_LIST'); return; } await deleteBattle(battleToDelete); setSavedBattles(prev => prev.filter(b => b.id !== battleToDelete)); if (battleId === battleToDelete) { setBattleId(null); setBattleName('Новый Бой'); setRound(0); setStatus('startup'); setLogs([]); setParticipants([]); setTree([]); } setActiveModal('BATTLE_LIST'); };
  const cancelDelete = () => { setBattleToDelete(null); setActiveModal('BATTLE_LIST'); };
  const handleCreateBattleClick = () => { setModalInput(''); setActiveModal('CREATE_BATTLE'); };
  const confirmCreateBattle = async () => { 
      setLoading(true); 
      const { data } = await createBattle(modalInput || "Стычка"); 
      if (data) { setBattleId(data.id); setBattleName(data.name); setRound(0); setStatus('startup'); setParticipants([]); setLogs([]); const { data: battles } = await getBattles(); if (battles) setSavedBattles(battles); } 
      setLoading(false); closeModal(); 
  };
  const handleSaveBattle = async () => {
      if (!battleId) {
          setPendingAction(() => async () => {
               const { data } = await createBattle(battleName);
                if (data) {
                    setBattleId(data.id);
                    await updateBattle(data.id, { participants_snapshot: participants, sequence_log: logs, round: round, status: status, casualties: [] });
                    const { data: battles } = await getBattles(); if (battles) setSavedBattles(battles);
                }
                closeModal();
          });
          setActiveModal('CONFIRM_SAVE');
      } else {
          await updateBattle(battleId, { name: battleName, participants_snapshot: participants, sequence_log: logs, round: round, status: status });
          showAlert("Бой успешно сохранен.");
      }
  };

  const addParticipant = (template: CharacterTemplate) => {
      const newP: BattleParticipant = {
          ...template, instance_id: `char_${template.id}_${Date.now()}`, is_player: false,
          battle_stats: { hp_penalty_current: 0, trauma_phys: 0, trauma_mag: 0, trauma_uniq: 0, actions_max: 4, actions_left: 4 },
          active_effects: [], cooldowns: [], usage_counts: {}, flat_abilities: [], flat_passives: []
      };

      // Passives Logic: Check for 'Combat Start' triggers and log them
      const startPassives = newP.flat_passives.filter(p => {
          const t = p.trigger?.toLowerCase() || '';
          return t === 'combat start' || t === 'начало боя';
      });

      if (startPassives.length > 0) {
          const lines = startPassives.map(p => `> ${newP.profile.name}: ${p.name} (${p.desc_mech || 'Нет описания'})`);
          const newLog: LogEntry = {
              id: `sys-${Date.now()}`,
              round: round,
              timestamp: new Date().toISOString(),
              type: 'system',
              text_formatted: `[ПАССИВНО] ${newP.profile.name} активирует способности начала боя:\n${lines.join('\n')}`
          };
          setLogs(prev => [...prev, newLog]);
      }

      setParticipants(prev => [...prev, newP]);
      setActiveModal(null);
  };

  const handleNextRound = async () => { setRound(r => r + 1); };
  const handleRollback = async (targetRound: number) => { };
  const handleEndBattleClick = () => { setActiveModal('FINALIZE_BATTLE'); };

  const handleCommit = async () => {
      if (tree.length === 0) {
          showAlert("Последовательность пуста. Нечего выполнять.");
          return;
      }

      // Calculate the sequence
      const result = calculateSequenceTree(tree, participants);

      if (!result.formattedString) {
          showAlert("Не удалось сформировать результат. Проверьте связи.");
          return;
      }

      const newLog: LogEntry = {
          id: `seq-${Date.now()}`,
          round: round,
          timestamp: new Date().toISOString(),
          type: 'action',
          text_formatted: result.formattedString
      };

      setLogs(prev => [...prev, newLog]);
      setTree([]); // Clear builder after commit? Optional, but cleaner.
  };

  const handleDragStart = (e: DragStartEvent) => { if (e.active.data.current?.type === 'SOURCE_ABILITY') setActiveDragItem(e.active.data.current); else if (e.active.data.current?.type === 'NODE') setActiveNode(e.active.data.current?.node); };
  const handleDragEnd = (e: DragEndEvent) => { };
  const removeNode = (id: string) => { setTree(prev => prev.filter(n => n.id !== id)); };
  const updateNodeData = (id: string, data: any) => { };
  const addBlock = (type: any) => { };
  const handleAddLogicSibling = (id: string) => {};

  return (
    <DndContext sensors={sensors} collisionDetection={pointerWithin} onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
        {/* Modals */}
        <Modal isOpen={activeModal === 'CHAR_SELECT'} onClose={closeModal} title="Добавить участника">
            <div className="flex flex-col gap-3 mb-4">
                <input type="text" placeholder="ПОИСК..." value={charSearchTerm} onChange={(e) => setCharSearchTerm(e.target.value)} className="w-full bg-input border border-violet-900/40 rounded p-2 text-sm text-white" />
            </div>
            <div className="space-y-2 max-h-64 overflow-y-auto pr-1">
                {filteredCharacters.map(c => (
                    <button key={c.id} onClick={() => addParticipant(c)} className={`w-full text-left p-3 rounded border flex justify-between items-center transition-all duration-300 hover:shadow-glow ${getCharacterStyle(c.profile.faction)}`}>
                        <span className="font-bold">{c.profile.name}</span>
                    </button>
                ))}
            </div>
        </Modal>

        {/* --- Main Content (Scrollable Page) --- */}
        <div className="min-h-screen bg-slate-950 text-slate-300 font-sans p-4 flex flex-col">
            {/* Header */}
            <header className="mb-4 flex items-center justify-between bg-panel p-4 rounded-lg border border-violet-900/30 shadow-lg relative overflow-hidden group shrink-0">
                <div className="flex items-center gap-4 relative z-10">
                     <button onClick={() => setActiveModal('BATTLE_LIST')} className="p-2 bg-slate-900 hover:bg-violet-900/40 rounded border border-violet-900/50 text-violet-300 hover:text-white transition-all hover:shadow-glow" title="Архив">
                         <List size={18} />
                     </button>
                     <button onClick={handleSaveBattle} className="p-2 bg-slate-900 hover:bg-emerald-900/40 rounded border border-violet-900/50 text-violet-300 hover:text-emerald-300 hover:border-emerald-500/50 transition-all hover:shadow-glow" title="Сохранить">
                         <Save size={18} />
                     </button>
                     <div>
                         <input 
                            value={battleName} 
                            onChange={(e) => setBattleName(e.target.value)}
                            className="bg-transparent text-xl font-bold font-rune text-transparent bg-clip-text bg-gradient-to-r from-violet-200 to-fuchsia-200 outline-none w-64"
                         />
                         <div className="text-xs text-slate-500 flex items-center gap-2 font-mono mt-1">
                            <span>СТАТУС:</span>
                            <span className={`uppercase font-bold tracking-wider ${status === 'active' ? 'text-emerald-400' : 'text-amber-400'}`}>{getStatusLabel(status)}</span>
                         </div>
                     </div>
                </div>

                <div className="flex items-center gap-6 relative z-10">
                     <div className="text-right mr-4">
                        <div className="text-[10px] text-violet-400 uppercase tracking-[0.2em] font-bold">Раунд</div>
                        <div className="font-bold text-3xl font-rune text-white drop-shadow-md">{round}</div>
                     </div>

                     {status !== 'finished' && (
                         <>
                            <button onClick={handleNextRound} className="flex items-center gap-2 bg-slate-900 hover:bg-emerald-900/30 text-emerald-400 border border-emerald-900/50 px-5 py-2 rounded-sm font-bold font-rune uppercase text-xs tracking-widest transition-all">
                                <Play size={14} /> {round === 0 ? "НАЧАТЬ БОЙ" : "След. Раунд"}
                            </button>
                            <button onClick={handleEndBattleClick} className="flex items-center gap-2 bg-slate-900 hover:bg-red-900/30 text-red-400 border border-red-900/50 px-5 py-2 rounded-sm font-bold font-rune uppercase text-xs tracking-widest transition-all">
                                <Square size={14} /> Завершить
                            </button>
                         </>
                     )}
                </div>
            </header>

            <main className="flex-1 grid grid-cols-1 md:grid-cols-12 gap-4 pb-20">
                {/* LEFT PANEL: Participants */}
                <div className="col-span-12 md:col-span-3 flex flex-col">
                     <div className="flex items-center justify-between mb-3 px-1 border-b border-violet-900/30 pb-2 shrink-0">
                        <h2 className="text-xs font-bold text-violet-400 uppercase tracking-widest font-rune">Участники</h2>
                        <button onClick={() => setActiveModal('CHAR_SELECT')} className="text-violet-400 hover:text-white transition-all">
                            <UserPlus size={18} />
                        </button>
                     </div>
                     <SourcePanel 
                        participants={participants} 
                        onToggleEquip={handleToggleEquip}
                        onRemoveParticipant={handleRemoveParticipant}
                        onAddInjury={handleAddInjury}
                        onRemoveInjury={handleRemoveInjury}
                        onAddDebuff={handleAddDebuff}
                        onRemoveEffect={handleRemoveEffect}
                        onRemoveCooldown={handleRemoveCooldown}
                     />
                </div>

                {/* CENTER PANEL: Canvas */}
                <div className="col-span-12 md:col-span-6 flex flex-col gap-3 min-h-[500px]">
                     <div className="flex-1 relative border border-violet-900/20 rounded bg-black/20 min-h-[400px]">
                         <SequenceCanvas 
                            tree={tree}
                            participants={participants}
                            onRemove={removeNode}
                            onUpdateData={updateNodeData}
                            onAddCombo={() => addBlock('combo')}
                            onAddCondition={() => addBlock('condition')}
                            onAddDivider={() => addBlock('divider')}
                            onClear={() => setTree([])}
                            onAddLogicSibling={handleAddLogicSibling}
                         />
                    </div>
                    <button onClick={handleCommit} className="w-full font-bold py-3 rounded shadow-lg uppercase tracking-[0.2em] font-rune bg-violet-900/60 border border-violet-500/50 text-white hover:bg-violet-800/80 transition-all">
                        <RefreshCw size={18} className="inline mr-2" /> Выполнить
                    </button>
                </div>

                {/* RIGHT PANEL: Logs */}
                <div className="col-span-12 md:col-span-3 min-h-[500px]">
                     <BattleLog 
                        logs={logs} 
                        currentRound={round} 
                        participants={participants}
                        onUpdateLogs={setLogs}
                        onUpdateParticipant={handleUpdateParticipant}
                        onRollback={handleRollback}
                     />
                </div>
            </main>
        </div>

        <DragOverlay>
            {activeDragItem && <div className="bg-violet-900 p-2 rounded text-white">Ability</div>}
        </DragOverlay>
    </DndContext>
  );
};

export default BattleModule;
